{
  "name": "ctxray-workspace",
  "private": true,
  "type": "module",
  "packageManager": "bun@1.4.4",
  "workspaces": [
    "packages/*"
  ],
  "imports": {
    "#ctxray/*": "./packages/ctxray/src/*"
  },
  "scripts": {
    "check": "biome check . && tsc -p . && tsc -p tsconfig.client.json && bun scripts/check-file-size.ts",
    "fix": "biome check --write .",
    "typecheck": "tsc -p . && tsc -p tsconfig.client.json",
    "schemas": "bun scripts/gen-schemas.ts",
    "gitleaks": "bun scripts/gen-gitleaks.ts",
    "build": "bun scripts/build.ts"
  },
  "devDependencies": {
    "@biomejs/biome": "2.6.7",
    "@types/bun": "1.4.4",
    "typescript": "7.0.2"
  }
}

{
  "name": "@mairwunnx/ctxray",
  "version": "0.1.0",
  "description": "X-ray for agent harnesses. See exactly what your Claude Code, Codex, Cursor & co. loaded – and test it in CI.",
  "license": "MIT",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/MairwunNx/ctxray.git",
    "directory": "packages/ctxray"
  },
  "homepage": "https://github.com/MairwunNx/ctxray/wiki",
  "bugs": "https://github.com/MairwunNx/ctxray/issues",
  "engines": {
    "bun": ">=1.4.4"
  },
  "exports": {
    ".": "./src/app/public-api.ts"
  },
  "imports": {
    "#app/*": "./src/app/*",
    "#features/*": "./src/features/*",
    "#entities/*": "./src/entities/*",
    "#shared/*": "./src/shared/*",
    "#fixtures/*": "./fixtures/*",
    "#package.json": "./package.json"
  },
  "bin": {
    "ctxray": "./src/app/main.ts"
  },
  "dependencies": {
    "@huggingface/tokenizers": "0.2.0",
    "braces": "3.0.3",
    "elysia": "1.4.32",
    "gpt-tokenizer": "4.1.2",
    "ignore": "7.0.14",
    "ink": "8.0.0",
    "marked": "18.2.0",
    "p-map": "7.1.1",
    "react": "19.3.1",
    "typed-inject": "5.0.0",
    "zod": "4.6.7"
  },
  "devDependencies": {
    "@types/braces": "3.0.5",
    "@types/react": "19.3.0"
  }
}

{
  "version": "1.19.5",
  "model": "claude-sonnet-5-5",
  "read": "app/src/main/kotlin/payments/Charge.kt",
  "servers": {
    "jira": {
      "info": {
        "name": "jira",
        "version": "1.0.0"
      },
      "instructions": "Use the jira tools to look up tickets of the PAY project.",
      "tools": [
        {
          "name": "search_issues",
          "description": "Search Jira issues with JQL.",
          "inputSchema": {
            "type": "object",
            "properties": {
              "jql": {
                "type": "string",
                "description": "JQL query"
              }
            },
            "required": ["jql"]
          }
        }
      ],
      "calls": []
    },
    "github": {
      "info": {
        "name": "github",
        "version": "1.0.0"
      },
      "instructions": "Use the github tools for issues and pull requests of the payments repositories.",
      "tools": [
        {
          "name": "create_issue",
          "description": "Open an issue in a repository.",
          "inputSchema": {
            "type": "object",
            "properties": {
              "repo": {
                "type": "string",
                "description": "owner/name"
              },
              "title": {
                "type": "string",
                "description": "Issue title"
              },
              "body": {
                "type": "string",
                "description": "Markdown body"
              }
            },
            "required": ["repo", "title", "body"]
          }
        },
        {
          "name": "list_pulls",
          "description": "List open pull requests of a repository.",
          "inputSchema": {
            "type": "object",
            "properties": {
              "repo": {
                "type": "string",
                "description": "owner/name"
              }
            },
            "required": ["repo"]
          }
        }
      ],
      "calls": []
    }
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "mcp": {
    "github": {
      "type": "local",
      "command": ["sh", "-c", "exec bun \"$(git rev-parse --show-toplevel)/mcp/server.ts\" github"]
    },
    "jira": {
      "type": "local",
      "command": ["sh", "-c", "exec bun \"$(git rev-parse --show-toplevel)/mcp/server.ts\" jira"]
    }
  }
}
